targets.source:
count by (node) (
  count by (node, gpu, UUID) (
    ${MetricPrefix:raw}DCGM_FI_DEV_FB_USED{bcs_cluster_id="$Cluster"}
  )
)

100 * avg by (node, gpu, UUID, GPU_I_ID, GPU_I_PROFILE, pod_name) (
  ${MetricPrefix:raw}DCGM_FI_PROF_PIPE_TENSOR_ACTIVE{
    bcs_cluster_id="$Cluster",
    GPU_I_ID!=""
  }
)

100 * avg by (node, gpu, UUID, GPU_I_ID, GPU_I_PROFILE, pod_name) (
  ${MetricPrefix:raw}DCGM_FI_PROF_DRAM_ACTIVE{
    bcs_cluster_id="$Cluster",
    GPU_I_ID!=""
  }
)

avg by (node, gpu, UUID, GPU_I_ID) (
  ${MetricPrefix:raw}DCGM_FI_DEV_FB_USED{bcs_cluster_id="$Cluster", pod_name=""}
)

sum by (pod_name) (
  max by (pod_name, node, gpu, UUID) (
    ${MetricPrefix:raw}DCGM_FI_DEV_TOTAL_ENERGY_CONSUMPTION{bcs_cluster_id="$Cluster", pod_name=~"$Pod"}
  )
) / 1000

sum by (pod_name) (
  max by (pod_name, node, gpu, UUID) (
    increase(${MetricPrefix:raw}DCGM_FI_DEV_TOTAL_ENERGY_CONSUMPTION{bcs_cluster_id="$Cluster", pod_name=~"$Pod"}[5m])
  )
) / 1000

sum by (pod_name) (
  max by (pod_name, node, gpu, UUID) (
    increase(${MetricPrefix:raw}DCGM_FI_DEV_TOTAL_ENERGY_CONSUMPTION{bcs_cluster_id="$Cluster", pod_name=~"$Pod"}[1h])
  )
) / 3600000000
